import asyncio, json, sys, os, time
for k in ("HTTP_PROXY","HTTPS_PROXY","http_proxy","https_proxy"):
    os.environ.pop(k, None)
import urllib.request, websockets

def get_target():
    with urllib.request.urlopen("http://localhost:1337/json") as r:
        data = json.loads(r.read())
    for t in data:
        if t.get("type") == "page" and "webext" in t.get("url", ""):
            return t["webSocketDebuggerUrl"]
    raise SystemExit("no target")

async def run():
    ws_url = get_target()
    async with websockets.connect(ws_url, max_size=None) as ws:
        mid = [0]
        async def call(method, params=None):
            mid[0] += 1
            i = mid[0]
            await ws.send(json.dumps({"id": i, "method": method, "params": params or {}}))
            while True:
                resp = json.loads(await ws.recv())
                if resp.get("id") == i:
                    if "error" in resp:
                        print("ERR", method, resp["error"])
                    return resp.get("result", {})

        # Enable Page domain to set download behavior
        await call("Page.enable")
        await call("Browser.setDownloadBehavior", {
            "behavior": "allow",
            "downloadPath": "/tmp/webext-dl",
            "eventsEnabled": True
        })

        # Run the wizard end-to-end via JS
        script = r"""
        (async () => {
          // start
          window.changeScreen('questions');
          // set name
          const nameInput = document.querySelector('input[data-question="name"]');
          nameInput.value = 'happy-extension';
          nameInput.nextElementSibling.click();  // .go arrow
          // description blank
          const descInput = document.querySelector('input[data-question="description"]');
          descInput.value = '';
          descInput.nextElementSibling.click();
          // version
          const verInput = document.querySelector('input[data-question="version"]');
          verInput.value = '0.0.1';
          verInput.nextElementSibling.click();
          // background_script: yes -> next 5
          window.setValue('background_script', true, 5);
          // content_script: no -> next 6
          window.setValue('content_script', false, 6);
          // browser_action: yes -> next 7
          window.setValue('browser_action', true, 7);
          // page_action: no -> next 8
          window.setValue('page_action', false, 8);
          // options_ui: no -> next 0 (triggers build/download + thanks)
          window.setValue('options_ui', false, 0);
          // wait a bit for promise to start
          await new Promise(r => setTimeout(r, 500));
          return 'ok';
        })()
        """
        r = await call("Runtime.evaluate", {"expression": script, "awaitPromise": True, "returnByValue": True})
        print("script:", json.dumps(r.get("result", {}), indent=2))

        # Wait for download events
        deadline = time.time() + 20
        downloaded = None
        while time.time() < deadline:
            try:
                resp = json.loads(await asyncio.wait_for(ws.recv(), timeout=2))
                if resp.get("method", "").startswith("Browser.downloadProgress") or resp.get("method", "").startswith("Page.download"):
                    print("evt:", resp.get("method"), json.dumps(resp.get("params", {}))[:200])
                    if resp.get("method") == "Browser.downloadProgress" and resp["params"].get("state") == "completed":
                        downloaded = resp["params"]
                        break
            except asyncio.TimeoutError:
                # Check filesystem instead
                files = [f for f in os.listdir("/tmp/webext-dl") if f.endswith(".zip")]
                if files:
                    print("found file:", files)
                    break

asyncio.run(run())
